function upstreamRequest(request, target) {
  const headers = new Headers(request.headers);
  headers.delete("host");
  headers.delete("cookie");
  headers.delete("authorization");
  return new Request(target, {
    method: request.method,
    headers,
    redirect: "follow",
    cache: "no-store",
  });
}

export default {
  async fetch(request) {
    const incoming = new URL(request.url);

    if (incoming.pathname === "/carrier-network" || incoming.pathname === "/carrier-network/") {
      return Response.redirect(new URL("/solutions", incoming), 302);
    }

    if (incoming.pathname === HOMEPAGE_REPAIR_SCRIPT) {
      const script = `(() => {
  const solutionsRelease = "20260721-v33";
  const forceSolutionsDocumentNavigation = (event) => {
    if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    const link = event.target.closest?.("a[href]");
    if (!link) return;
    const destination = new URL(link.href, location.href);
    if (destination.pathname.replace(/\\/+$/, "") !== "/solutions") return;
    event.preventDefault();
    event.stopImmediatePropagation();
    destination.pathname = "/solutions/";
    destination.searchParams.set("wu-nav", solutionsRelease);
    location.assign(destination.href);
  };
  const repairHomepage = () => {
    const hero = document.querySelector('img[src="/assets/hero.webp"], img[src$="/assets/hero.webp"]');
    if (hero) {
      hero.setAttribute("width", "1672");
      hero.setAttribute("height", "941");
      hero.setAttribute("loading", "eager");
      hero.setAttribute("fetchpriority", "high");
      hero.setAttribute("decoding", "async");
    }
    document.querySelectorAll('img[src="/assets/logo.png"], img[src$="/assets/logo.png"]').forEach((logo) => {
      logo.setAttribute("width", "545");
      logo.setAttribute("height", "113");
      logo.setAttribute("decoding", "async");
    });
    document.querySelectorAll("article h3").forEach((heading) => {
      if (heading.textContent.trim() !== "Retirement & Legacy Solutions") return;
      heading.textContent = "Watts Unified Solutions";
      const card = heading.closest("article");
      if (!card) return;
      const image = card.querySelector("img");
      if (image) image.alt = "Watts Unified Solutions";
      const link = card.querySelector("a");
      if (link) link.setAttribute("href", "/solutions");
    });
    document.querySelectorAll("footer small, footer p").forEach((item) => {
      const copyright = "© 2026 Watts Unified Solutions. All rights reserved.";
      const currentText = item.textContent.trim();
      const isCopyright = currentText.includes("Watts Unified Solutions") && currentText.includes("All rights reserved.");
      if (isCopyright && currentText !== copyright) {
        item.textContent = copyright;
      }
    });
    const opportunityPathname = location.pathname.endsWith("/")
      ? location.pathname.slice(0, -1)
      : location.pathname;
    if (opportunityPathname === "/opportunity") {
      const opportunityFooter = document.querySelector("footer");
      if (opportunityFooter) {
        opportunityFooter.setAttribute("data-wu-footer", "navy-v1");
        const footerLogo = opportunityFooter.querySelector(".footer-brand img");
        if (footerLogo) {
          footerLogo.setAttribute("src", "/solutions-app/watts-brand-lockup.png");
          footerLogo.setAttribute("width", "545");
          footerLogo.setAttribute("height", "113");
          footerLogo.setAttribute("decoding", "async");
        }
      }
      const pathSection = document.querySelector("section.opportunity-paths");
      const pathImage = pathSection?.querySelector('img[src*="/assets/opportunity-paths.png"]');
      if (pathImage) {
        pathImage.setAttribute("width", "1901");
        pathImage.setAttribute("height", "577");
        pathImage.setAttribute("alt", "Choose Your Path");
        pathImage.setAttribute("loading", "lazy");
        pathImage.setAttribute("decoding", "async");
      }
      const pathLinks = pathSection ? Array.from(pathSection.querySelectorAll("a")) : [];
      const pathDestinations = [
        ["/opportunity/financial-professional", "Explore the Financial Services Partner path"],
        ["/opportunity/legalshield-independent-associate", "Explore the Legal Services Partner path"],
      ];
      pathDestinations.forEach(([href, label], index) => {
        const link = pathLinks[index];
        if (!link) return;
        link.setAttribute("href", href);
        link.setAttribute("aria-label", label);
      });
      const faqSection = document.querySelector("section.faq-section");
      if (faqSection && faqSection.getAttribute("data-wu-faq") !== "conversion-v2") {
        faqSection.setAttribute("data-wu-faq", "conversion-v2");
        faqSection.setAttribute("aria-label", "Frequently Asked Questions");
        faqSection.setAttribute("id", "opportunity-faq");
        const faqTitle = faqSection.querySelector(".section-title");
        if (faqTitle) {
          faqTitle.insertAdjacentHTML("afterbegin", '<p class="wu-faq-eyebrow">Questions before you start?</p>');
          faqTitle.insertAdjacentHTML("beforeend", '<p class="wu-faq-intro">Get clear answers, then choose the professional path that fits your goals.</p><a class="wu-faq-cta" href="/schedule/solutions" data-wu-event="opportunity_faq_connect">Talk With S. Alex</a>');
        }
        faqSection.querySelectorAll("details").forEach((item) => {
          item.setAttribute("name", "opportunity-faq");
          item.removeAttribute("open");
        });
      }
      const nextStepSection = document.querySelector("section.cta");
      if (nextStepSection && nextStepSection.getAttribute("data-wu-next-step") !== "conversion-v2") {
        nextStepSection.setAttribute("data-wu-next-step", "conversion-v2");
        nextStepSection.setAttribute("aria-label", "Next Steps");
        nextStepSection.innerHTML = [
          '<div class="wu-next-step-inner">',
          '<div class="wu-next-step-copy">',
          '<span class="wu-next-step-eyebrow">Fit Conversation</span>',
          '<h2>Talk Through the Right Path.</h2>',
          '<p>If you are looking for additional income, professional growth, or business ownership, start with a clear conversation before choosing a path.</p>',
          '</div>',
          '<div class="wu-next-step-action">',
          '<a class="wu-next-step-cta" href="/schedule/opportunity" data-wu-event="opportunity_fit_conversation">Book a Fit Conversation <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14"/><path d="m12 5 7 7-7 7"/></svg></a>',
          '<p class="wu-next-step-trust">No pressure. Clear answers. The right next step.</p>',
          '</div>',
          '</div>',
        ].join("");
      }
    }
  };
  document.addEventListener("click", forceSolutionsDocumentNavigation, true);
  repairHomepage();
  [250, 750, 2000].forEach((delay) => setTimeout(repairHomepage, delay));
  new MutationObserver(repairHomepage).observe(document.documentElement, {
    childList: true,
    characterData: true,
    subtree: true,
  });
})();`;
      return new Response(script, {
        headers: {
          "content-type": "application/javascript; charset=UTF-8",
          "cache-control": "no-store",
          "x-watts-homepage-repair": "opportunity-next-step-v2",
          "x-content-type-options": "nosniff",
        },
      });
    }

    if (incoming.pathname === ALIGNABLE_ICON_PATH) {
      return new Response(ALIGNABLE_ICON, {
        headers: {
          "content-type": "image/svg+xml; charset=UTF-8",
          "cache-control": "no-store",
          "x-watts-social-icon": "alignable-official-v2",
          "x-content-type-options": "nosniff",
        },
      });
    }

    if (incoming.pathname === OPPORTUNITY_PATHS_IMAGE_PATH) {
      return new Response(getOpportunityPathsImageBytes(), {
        headers: {
          "content-type": "image/webp",
          "cache-control": "public, max-age=31536000, immutable",
          "x-watts-home-image": "opportunity-paths-original-v1",
          "x-content-type-options": "nosniff",
        },
      });
    }

    const stableImage = HOMEPAGE_IMAGE_REPLACEMENTS.get(incoming.pathname);
    if (stableImage) {
      const response = await fetch(upstreamRequest(request, `${STABLE_SITE}${stableImage}`));
      const headers = new Headers(response.headers);
      headers.set("content-type", "image/webp");
      headers.set("cache-control", "no-cache");
      headers.set("x-watts-home-image", "stable-site-image-v2");
      headers.set("x-content-type-options", "nosniff");
      headers.delete("content-length");
      return new Response(response.body, { status: response.status, headers });
    }

    const originUrl = new URL(incoming.pathname + incoming.search, ORIGIN);
    const originRequest = new Request(originUrl, request);
    const originResponse = await fetch(new Request(originRequest, { cache: "no-store" }));

    if (incoming.pathname === APP_ASSET) {
      const source = patchAppBundle(await originResponse.text());
      return new Response(source, {
        status: originResponse.status,
        headers: {
          "content-type": "application/javascript;charset=UTF-8",
          "cache-control": "no-store",
          "x-content-type-options": "nosniff",
        },
      });
    }

    const contentType = originResponse.headers.get("content-type") || "";
    if (contentType.includes("text/html") && isManagedHtmlPath(incoming.pathname)) {
      const html = patchHomepageHtml(await originResponse.text(), incoming.pathname === "/", incoming.pathname);
      return new Response(html, {
        status: originResponse.status,
        headers: {
          "content-type": "text/html;charset=UTF-8",
          "cache-control": "no-store",
          "x-content-type-options": "nosniff",
        },
      });
    }

    return originResponse;
  },
};
